#pragma once
// Palette entries for the rope nodes (docs/plans/wave11/SOFTBODY_HAIR.md 2.7). NOT standalone: GraphNodeFamilies.gen.inc (generated by
// cmake/GraphNodeFamilies.cmake) includes it from GraphNodeDefs.hpp inside namespace aver::editor::detail, after pin()/attr() are
// defined, and calls appendRopeNodeDefs(t).
//
// MIRRORS scripting/csharp/Aver.Graph/GraphRopeNodeTable.cs pin for pin. A rope is its entity id (0 = none), never a Jolt handle. End 0 is the
// start and 1 the end; Set End pins an end to a point of an entity (the offset is in that entity's space), Free End puts it at a world point
// (pinned) or lets it go. Cut splits the rope at its node nearest the point: the rope keeps the start, `other` is the new entity with the rest.

inline void appendRopeNodeDefs(std::vector<GraphNodeDesc>& t) {
    t.push_back({"CreateRope", "Create Rope", "Physics", {
        pin("exec", "exec", false), pin("x1", "float", false), pin("y1", "float", false), pin("z1", "float", false),
        pin("x2", "float", false), pin("y2", "float", false), pin("z2", "float", false),
        pin("length", "float", false, "0"), pin("radius", "float", false, "0"),
        pin("then", "exec", true), pin("entity", "int", true), pin("success", "bool", true)},
        {attr("asset", "Rope asset (.ocsoft of kind rope; empty = the rope preset)")}});
    t.push_back({"SetRopeEnd", "Set Rope End", "Physics", {
        pin("exec", "exec", false), pin("rope", "int", false), pin("end", "int", false), pin("anchor", "int", false),
        pin("ox", "float", false), pin("oy", "float", false), pin("oz", "float", false),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"FreeRopeEnd", "Free Rope End", "Physics", {
        pin("exec", "exec", false), pin("rope", "int", false), pin("end", "int", false),
        pin("x", "float", false), pin("y", "float", false), pin("z", "float", false), pin("pinned", "bool", false),
        pin("then", "exec", true), pin("success", "bool", true)}});
    t.push_back({"CutRope", "Cut Rope", "Physics", {
        pin("exec", "exec", false), pin("rope", "int", false), pin("x", "float", false), pin("y", "float", false), pin("z", "float", false),
        pin("then", "exec", true), pin("other", "int", true), pin("success", "bool", true)}});
    t.push_back({"GetRope", "Get Rope", "Physics", {
        pin("rope", "int", false), pin("found", "bool", true), pin("length", "float", true), pin("strain", "float", true),
        pin("nodes", "int", true), pin("cut", "bool", true)}});
    t.push_back({"DestroyRope", "Destroy Rope", "Physics", {
        pin("exec", "exec", false), pin("rope", "int", false), pin("then", "exec", true), pin("success", "bool", true)}});
}
